__global__ void matrix_mul_kernel_shared_memory(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; ++tile) {
        // Load tiles from global memory to shared memory
        int a_row = blockIdx.y * TILE_SIZE + threadIdx.y;
        int a_col = tile * TILE_SIZE + threadIdx.x;
        if (a_row < N && a_col < N) {
            sA[threadIdx.y][threadIdx.x] = A[a_row * N + a_col];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        int b_row = tile * TILE_SIZE + threadIdx.y;
        int b_col = blockIdx.x * TILE_SIZE + threadIdx.x;
        if (b_row < N && b_col < N) {
            sB[threadIdx.y][threadIdx.x] = B[b_row * N + b_col];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        __syncthreads();

