    int col = blockIdx.x * blockDim.x + threadIdx.x;

    // Each thread computes BLOCK_ROWS x BLOCK_COLS elements of the C matrix
    float C_reg[BLOCK_ROWS][BLOCK_COLS] = {0.0f};

    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; ++tile) {
        // Load tiles from global memory to shared memory
        // Each thread loads one element for sA and one for sB
