                int a_col_global = tile * TILE_SIZE + threadIdx.x + c * blockDim.x;
                if (a_row_global < N && a_col_global < N) {
                    sA[threadIdx.y + r * blockDim.y][threadIdx.x + c * blockDim.x] = A[a_row_global * N + a_col_global];
                } else {
                    sA[threadIdx.y + r * blockDim.y][threadIdx.x + c * blockDim.x] = 0.0f;
                }

                int b_row_global = tile * TILE_SIZE + threadIdx.y + r * blockDim.y;
                int b_col_global = blockIdx.x * TILE_SIZE + threadIdx.x + c * blockDim.x;
                if (b_row_global < N && b_col_global < N) {
