                } else {
                    sB[threadIdx.y + r * blockDim.y][threadIdx.x + c * blockDim.x] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Perform multiplication for the current tile using register blocking and unrolling
        for (int k = 0; k < TILE_SIZE; ++k) {
            #pragma unroll
            for (int r_block = 0; r_block < BLOCK_ROWS; ++r_block) {
                #pragma unroll
                for (int c_block = 0; c_block < BLOCK_COLS; ++c_block) {
