    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    // Global row and column for the top-left element of the thread's output block
    int global_row_base = (blockIdx.y * TILE_SIZE) + (threadIdx.y * BLOCK_ROWS);
    int global_col_base = (blockIdx.x * TILE_SIZE) + (threadIdx.x * BLOCK_COLS);

    // Each thread computes BLOCK_ROWS x BLOCK_COLS elements of the C matrix
    float C_reg[BLOCK_ROWS][BLOCK_COLS] = {0.0f};

    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; ++tile) {
        // Load tiles from global memory to shared memory
        // Each thread loads multiple elements to fill the shared memory tiles cooperatively
        #pragma unroll
        for (int r = 0; r < TILE_SIZE / blockDim.y; ++r) { 
            #pragma unroll
            for (int c = 0; c < TILE_SIZE / blockDim.x; ++c) { 
                // Calculate global indices for loading A
                int a_row_global = blockIdx.y * TILE_SIZE + threadIdx.y * (TILE_SIZE / blockDim.y) + r;
                int a_col_global = tile * TILE_SIZE + threadIdx.x * (TILE_SIZE / blockDim.x) + c;

                // Calculate global indices for loading B
