                int sB_col_idx = threadIdx.x * (TILE_SIZE / blockDim.x) + c;


                if (a_row_global < N && a_col_global < N) {
                    sA[sA_row_idx][sA_col_idx] = A[a_row_global * N + a_col_global];
                } else {
                    sA[sA_row_idx][sA_col_idx] = 0.0f;
